import subprocess
import sys

r = subprocess.run([sys.executable, "-c", "print('hello from the process')"],
                   capture_output=True, text=True, check=True)
print(r.returncode, r.stdout.strip())
try:
    subprocess.run([sys.executable, "-c", "raise SystemExit(3)"], check=True)
except subprocess.CalledProcessError as e:
    print("code", e.returncode)
try:
    subprocess.run([sys.executable, "-c", "import time; time.sleep(5)"], timeout=0.2)
except subprocess.TimeoutExpired:
    print("timeout")

import argparse
import sys

def total(nums):
    return sum(nums)

def main(argv=None):
    p = argparse.ArgumentParser()
    p.add_argument("nums", nargs="*", type=int)
    args = p.parse_args(argv)
    if not args.nums:
        print("no numbers", file=sys.stderr)
        return 1
    print(total(args.nums))
    return 0

if __name__ == "__main__":
    code = main(["1", "2", "3"])
    print("code", code)
